const STUDIO_OVERRIDES = (pathname, method) => {
  if (method !== 'GET') return undefined
  if (pathname === '/api/product/home') return HOME
  if (pathname === '/api/product/goals') return { items: [GOAL] }
  if (pathname === `/api/product/goals/${GOAL_ID}`) return GOAL_DETAIL
  if (pathname === '/api/product/reflection/review/902') return REFLECTION
  if (pathname === '/api/product/practice/options') return PRACTICE_OPTIONS
  if (pathname === '/api/product/history') return HISTORY_ITEMS
  if (pathname === '/api/intelligence/facts') return MY_FACTS
  if (pathname === '/api/intelligence/voice-preferences') return MY_VOICE
  if (pathname === '/api/product/quick-notes') return QUICK_NOTES
  if (pathname === '/api/intelligence/stories') return MY_STORIES
  if (pathname === '/api/product/stories/coverage') return STORY_COVERAGE
  if (pathname === '/api/product/materials') return PROJECT_MATERIALS
  if (pathname === '/api/intelligence/skill-cards') return MY_SKILLS
  if (pathname === '/api/kb/status') return KB_STATUS
  if (pathname === '/api/product/question-banks') return QUESTION_BANKS
  if (pathname.startsWith('/api/product/question-banks/') && pathname.endsWith('/items')) {
    const bankId = pathname.split('/')[4]
    return QUESTION_BANK_ITEMS[bankId] ?? { items: [] }
  }
  if (pathname === '/api/product/fact-inbox') return { count: 0, items: [], batch: null, merge_suggestions: [], policy: { mode: 'STANDARD', reasons: [] } }
  return undefined
}

const SNAPSHOT = {
  fullPage: false,
  timeout: 30_000,
}

async function expectInterviewStudioNav(page) {
  const nav = page.getByRole('navigation', { name: '主导航' })
  await expect(nav).toBeVisible()
  for (const label of ['首页', '求职目标', '练习', '历史', '我的成竹']) {
    await expect(nav.getByRole('button', { name: label })).toBeVisible()
  }
  await expect(nav.getByRole('button', { name: '资料库' })).toHaveCount(0)
}

